import { supabase } from '@/lib/supabase'
import { NextRequest, NextResponse } from 'next/server'

export const dynamic = 'force-dynamic'
export const fetchCache = 'force-no-store'

const CATEGORY_KEYWORDS: Record<string, string[]> = {
  vegetables: [
    'tomato', 'capsicum', 'brinjal', 'eggplant', 'bean', 'pea', 'pumpkin',
    'gourd', 'onion', 'potato', 'garlic', 'carrot', 'radish', 'cucumber',
    'okra', 'ladyfinger', 'drumstick', 'ridge gourd', 'bottle gourd', 'chilli',
    'pepper', 'bitter gourd', 'cluster bean', 'snake gourd',
  ],
  fruits: [
    'mango', 'banana', 'papaya', 'guava', 'pomegranate', 'orange', 'lime',
    'lemon', 'coconut', 'tamarind', 'jackfruit', 'sapota', 'fig', 'grapes',
    'watermelon', 'muskmelon', 'pineapple', 'custard apple',
  ],
  grains: [
    'rice', 'wheat', 'jowar', 'bajra', 'ragi', 'maize', 'corn', 'dal',
    'lentil', 'chickpea', 'groundnut', 'sesame', 'turmeric', 'ginger',
    'pulses', 'toor', 'moong', 'urad', 'chana',
  ],
  leafy: [
    'spinach', 'methi', 'fenugreek', 'coriander', 'mint', 'curry',
    'amaranth', 'sorrel', 'moringa', 'drumstick leaves', 'palak',
  ],
}

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url)
  const q = searchParams.get('q') ?? ''
  const method = searchParams.get('method') ?? ''
  const category = searchParams.get('category') ?? ''

  const { data: produce } = await supabase
    .from('produce_listings')
    .select('*')
    .eq('status', 'available')
    .order('created_at', { ascending: false })

  let filtered = produce ?? []

  if (q) {
    const query = q.toLowerCase()
    filtered = filtered.filter(
      (p) =>
        p.name?.toLowerCase().includes(query) ||
        p.variety?.toLowerCase().includes(query) ||
        p.description?.toLowerCase().includes(query)
    )
  }

  if (method && method !== 'all') {
    filtered = filtered.filter((p) =>
      p.method?.toLowerCase().includes(method.toLowerCase())
    )
  }

  if (category && category !== 'all' && CATEGORY_KEYWORDS[category]) {
    const keywords = CATEGORY_KEYWORDS[category]
    filtered = filtered.filter((p) =>
      keywords.some((kw) => p.name?.toLowerCase().includes(kw))
    )
  }

  if (!filtered.length) return NextResponse.json([])

  const farmerIds = [...new Set(filtered.map((p) => p.farmer_id))]

  const { data: farmers } = await supabase
    .from('farmers')
    .select('id, name, village, slug, phone, method, pickup_locations, pickup_slots')
    .in('id', farmerIds)
    .eq('active', true)

  const farmerMap = Object.fromEntries((farmers ?? []).map((f) => [f.id, f]))

  const result = filtered
    .map((p) => ({ ...p, farmer: farmerMap[p.farmer_id] ?? null }))
    .filter((p) => p.farmer !== null)

  return NextResponse.json(result)
}

'use client'

import { useState, useRef, useEffect } from 'react'

type Suggestion = {
  name: string
  subtitle: string
  lat: number
  lng: number
}

// AP + Telangana bbox: min_lon,min_lat,max_lon,max_lat
const BBOX = '76.0,12.0,85.5,20.5'

// States we allow in results
const ALLOWED_STATES = ['andhra pradesh', 'telangana']

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function parsePhoton(data: any): Suggestion[] {
  const seen = new Set<string>()
  const results: Suggestion[] = []

  for (const feature of data?.features ?? []) {
    const p = feature?.properties ?? {}
    const coords: [number, number] = feature?.geometry?.coordinates ?? [0, 0]
    const lng = coords[0]
    const lat = coords[1]

    if (!lat || !lng) continue

    // Filter to AP + Telangana only
    const state: string = (p.state ?? '').toLowerCase()
    if (state && !ALLOWED_STATES.some((s) => state.includes(s))) continue

    // Best name for this result
    const name: string = (
      p.name || p.city || p.town || p.village || p.hamlet || p.suburb || p.county || ''
    ).trim()
    if (!name) continue

    const key = name.toLowerCase()
    if (seen.has(key)) continue
    seen.add(key)

    const parts: string[] = []
    const district = p.county || p.district || p.state_district
    if (district && district.toLowerCase() !== key) parts.push(district)
    if (p.state) parts.push(p.state)

    results.push({ name, subtitle: parts.join(', '), lat, lng })
  }

  return results
}

async function fetchSuggestions(q: string, signal: AbortSignal): Promise<Suggestion[]> {
  const url = new URL('https://photon.komoot.io/api/')
  url.searchParams.set('q', q)
  url.searchParams.set('limit', '8')
  url.searchParams.set('bbox', BBOX)
  url.searchParams.set('lang', 'en')

  const res = await fetch(url.toString(), { signal })
  if (!res.ok) throw new Error(`HTTP ${res.status}`)
  const json = await res.json()
  return parsePhoton(json)
}

export default function LocationSearch({
  placeholder = 'Search city, town or village... / పట్టణం వెతకండి',
  onSelect,
  initialValue = '',
}: {
  placeholder?: string
  onSelect: (lat: number, lng: number, name: string) => void
  initialValue?: string
}) {
  const [query, setQuery]             = useState(initialValue)
  const [suggestions, setSuggestions] = useState<Suggestion[]>([])
  const [loading, setLoading]         = useState(false)
  const [showDrop, setShowDrop]       = useState(false)
  const [noResults, setNoResults]     = useState(false)
  const [dropUp, setDropUp]           = useState(false)
  const abortRef     = useRef<AbortController | null>(null)
  const timerRef     = useRef<ReturnType<typeof setTimeout> | null>(null)
  const containerRef = useRef<HTMLDivElement>(null)
  const inputRef     = useRef<HTMLInputElement>(null)

  const doSearch = async (q: string) => {
    abortRef.current?.abort()
    const clean = q.trim()
    if (clean.length < 2) {
      setSuggestions([])
      setNoResults(false)
      setLoading(false)
      setShowDrop(false)
      return
    }
    abortRef.current = new AbortController()
    setLoading(true)
    setNoResults(false)
    try {
      const results = await fetchSuggestions(clean, abortRef.current.signal)
      setSuggestions(results)
      setNoResults(results.length === 0)
      setShowDrop(true)
    } catch (err: unknown) {
      if ((err as Error).name !== 'AbortError') {
        setSuggestions([])
        setNoResults(true)
      }
    } finally {
      setLoading(false)
    }
  }

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value
    setQuery(val)
    if (timerRef.current) clearTimeout(timerRef.current)
    timerRef.current = setTimeout(() => doSearch(val), 350)
    if (val.trim().length < 2) {
      setSuggestions([])
      setNoResults(false)
      setShowDrop(false)
    }
  }

  const handleSelect = (s: Suggestion) => {
    setQuery(s.name)
    setSuggestions([])
    setShowDrop(false)
    setNoResults(false)
    onSelect(s.lat, s.lng, s.name)
  }

  const handleClear = () => {
    setQuery('')
    setSuggestions([])
    setShowDrop(false)
    setNoResults(false)
    abortRef.current?.abort()
  }

  // Flip dropdown upward when the keyboard shrinks the visual viewport and
  // leaves insufficient space below the input to show results
  useEffect(() => {
    const vv = window.visualViewport
    if (!vv) return
    const update = () => {
      if (!inputRef.current) return
      const rect = inputRef.current.getBoundingClientRect()
      // Pixels available between the bottom of the input and the top of the keyboard
      const spaceBelow = vv.height + vv.offsetTop - rect.bottom
      setDropUp(spaceBelow < 220)
    }
    vv.addEventListener('resize', update)
    vv.addEventListener('scroll', update)
    return () => {
      vv.removeEventListener('resize', update)
      vv.removeEventListener('scroll', update)
    }
  }, [])

  // Close on outside click
  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setShowDrop(false)
      }
    }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [])

  useEffect(() => () => { abortRef.current?.abort() }, [])

  return (
    <div ref={containerRef} className="relative">
      {/* Input */}
      <div className="relative">
        <svg
          className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none"
          width="17" height="17" viewBox="0 0 24 24" fill="none"
          stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"
        >
          <circle cx="11" cy="11" r="8" />
          <path d="m21 21-4.35-4.35" />
        </svg>
        <input
          ref={inputRef}
          type="text"
          value={query}
          onChange={handleChange}
          onFocus={() => { if (suggestions.length > 0) setShowDrop(true) }}
          placeholder={placeholder}
          autoComplete="off"
          spellCheck={false}
          className="w-full border-2 border-gray-200 rounded-xl pl-9 pr-9 py-3 text-base focus:border-green-500 focus:outline-none bg-white"
        />
        {loading && (
          <span className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none">
            <span className="animate-spin inline-block w-4 h-4 border-2 border-green-600 border-t-transparent rounded-full" />
          </span>
        )}
        {!loading && query && (
          <button
            type="button"
            onMouseDown={(e) => { e.preventDefault(); handleClear() }}
            className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 text-xl leading-none"
          >
            ×
          </button>
        )}
      </div>

      {/* Suggestions dropdown */}
      {showDrop && suggestions.length > 0 && (
        <div className={`absolute z-30 left-0 right-0 bg-white border border-gray-200 rounded-xl shadow-xl overflow-hidden max-h-64 overflow-y-auto ${dropUp ? 'bottom-full mb-1' : 'top-full mt-1'}`}>
          {suggestions.map((s, i) => (
            <button
              key={i}
              type="button"
              onMouseDown={(e) => { e.preventDefault(); handleSelect(s) }}
              className="w-full text-left px-4 py-3 hover:bg-green-50 active:bg-green-100 border-b border-gray-100 last:border-0"
            >
              <p className="font-semibold text-sm text-gray-900 leading-snug">📍 {s.name}</p>
              {s.subtitle && (
                <p className="text-xs text-gray-500 mt-0.5">{s.subtitle}</p>
              )}
            </button>
          ))}
        </div>
      )}

      {/* No results */}
      {showDrop && noResults && !loading && (
        <div className={`absolute z-30 left-0 right-0 bg-white border border-gray-200 rounded-xl shadow-xl px-4 py-4 text-center ${dropUp ? 'bottom-full mb-1' : 'top-full mt-1'}`}>
          <p className="text-sm font-semibold text-gray-600">
            No results / ఫలితాలు లేవు
          </p>
          <p className="text-xs text-gray-400 mt-1 leading-snug">
            Try the full name or a nearby larger town<br />
            పూర్తి పేరు లేదా దగ్గరలోని పెద్ద పట్టణం వెతకండి
          </p>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState } from 'react'
import Link from 'next/link'
import { useLang } from '@/lib/LanguageContext'
import { useCart } from '@/components/consumer/Cart'

type ProduceItem = {
  id: string
  name: string
  variety?: string
  emoji?: string
  farmer_id: string
  price_tier_1_price?: number
  price_tier_1_qty?: number
  price_tier_2_price?: number
  price_tier_2_qty?: number
  price_tier_3_price?: number
  unit?: string
  stock_qty?: number
  method?: string
}

type Farmer = {
  id: string
  slug: string
  name: string
  village?: string
  phone?: string
  pickup_locations?: string[]
  rating_avg?: number
}

export default function BrowseProduceTab({
  produce,
  farmers,
}: {
  produce: Record<string, unknown>[]
  farmers: Record<string, unknown>[]
}) {
  const { tx } = useLang()
  const { addItem, cart } = useCart()
  const [search, setSearch] = useState('')
  const [addedIds, setAddedIds] = useState<Set<string>>(new Set())

  const list = produce as ProduceItem[]
  const farmerList = farmers as Farmer[]

  const getFarmer = (farmerId: string) => farmerList.find((f) => f.id === farmerId)

  const filtered = list.filter((p) => {
    if (!search.trim()) return true
    const q = search.toLowerCase()
    return (
      p.name.toLowerCase().includes(q) ||
      (p.variety ?? '').toLowerCase().includes(q)
    )
  })

  const handleAddToCart = (item: ProduceItem) => {
    const farmer = getFarmer(item.farmer_id)
    if (!farmer?.phone) return

    addItem({
      listingId: item.id,
      name: item.name,
      variety: item.variety,
      emoji: item.emoji,
      pricePerKg: item.price_tier_1_price,
      priceTier1Qty: item.price_tier_1_qty,
      priceTier1Price: item.price_tier_1_price,
      priceTier2Qty: item.price_tier_2_qty,
      priceTier2Price: item.price_tier_2_price,
      priceTier3Price: item.price_tier_3_price,
      unit: item.unit,
      stockQty: item.stock_qty,
      farmerId: farmer.id,
      farmerName: farmer.name,
      farmerPhone: farmer.phone,
      farmerVillage: farmer.village ?? '',
      farmerSlug: farmer.slug,
      farmerPickupLocations: farmer.pickup_locations,
    })

    setAddedIds((prev) => new Set(prev).add(item.id))
    setTimeout(() => {
      setAddedIds((prev) => {
        const next = new Set(prev)
        next.delete(item.id)
        return next
      })
    }, 2000)
  }

  if (list.length === 0) {
    return (
      <div className="text-center py-10 text-gray-400 text-sm">{tx.noProduceFound}</div>
    )
  }

  return (
    <div className="space-y-3">
      <input
        type="text"
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        placeholder={tx.searchProducePlaceholder}
        className="w-full border border-gray-200 rounded-xl px-4 py-2.5 text-sm focus:border-green-500 focus:outline-none bg-white"
      />

      {filtered.length === 0 ? (
        <div className="text-center py-8 text-gray-400 text-sm">{tx.noProduceFound}</div>
      ) : (
        <div className="grid grid-cols-2 gap-3">
          {filtered.map((item) => {
            const farmer = getFarmer(item.farmer_id)
            if (!farmer) return null
            const added = addedIds.has(item.id)
            const inCart = !!cart[item.id]
            const canCart = !!item.price_tier_1_price && !!farmer.phone

            return (
              <div key={item.id} className="bg-white rounded-xl border border-gray-100 overflow-hidden">
                <Link href={`/farmer/${farmer.slug}#produce`} className="block p-3">
                  <div className="text-3xl mb-2">{item.emoji ?? '🌿'}</div>
                  <h3 className="text-sm font-bold text-gray-900 leading-tight">{item.name}</h3>
                  {item.variety && (
                    <p className="text-[10px] text-gray-500 mt-0.5 truncate">{item.variety}</p>
                  )}
                  <p className="text-xs text-green-700 font-semibold mt-1 truncate">
                    {farmer.name}
                    {farmer.village ? ` · ${farmer.village}` : ''}
                  </p>
                  {farmer.rating_avg ? (
                    <div className="flex items-center gap-1 mt-0.5">
                      <span className="text-yellow-400 text-xs">★</span>
                      <span className="text-xs text-gray-500">{farmer.rating_avg.toFixed(1)}</span>
                    </div>
                  ) : null}
                  <div className="flex items-center justify-between mt-2">
                    {item.price_tier_1_price ? (
                      <span className="text-sm font-bold text-gray-900">
                        ₹{item.price_tier_1_price}
                        <span className="text-xs font-normal text-gray-400">/{item.unit ?? 'kg'}</span>
                      </span>
                    ) : (
                      <span />
                    )}
                    {item.method === 'natural' && (
                      <span className="bg-green-100 text-green-800 text-[10px] font-bold px-1.5 py-0.5 rounded-full">
                        Natural
                      </span>
                    )}
                  </div>
                  {item.stock_qty !== undefined && item.stock_qty > 0 && (
                    <p className="text-[10px] text-gray-400 mt-1">
                      {item.stock_qty} {item.unit ?? 'kg'} left
                    </p>
                  )}
                </Link>

                {canCart && (
                  <div className="px-3 pb-3">
                    <button
                      onClick={() => handleAddToCart(item)}
                      className={`w-full py-2 rounded-lg text-xs font-bold transition-colors ${
                        added
                          ? 'bg-green-100 text-green-800'
                          : inCart
                          ? 'bg-green-50 text-green-700 border border-green-300'
                          : 'bg-green-700 text-white active:bg-green-800'
                      }`}
                    >
                      {added ? tx.addedToCart : inCart ? `In cart ✓` : tx.addToCart}
                    </button>
                  </div>
                )}
              </div>
            )
          })}
        </div>
      )}
    </div>
  )
}

'use client'

import { useState } from 'react'
import { useLang } from '@/lib/LanguageContext'
import RegionMap from './RegionMap'
import FarmersTab from './tabs/FarmersTab'
import BrowseProduceTab from './tabs/BrowseProduceTab'
import AddFarmerTab from './tabs/AddFarmerTab'
import { CartFab } from '@/components/consumer/Cart'

const CATEGORY_MAP: Record<string, string[]> = {
  Vegetables: ['Tomato', 'Brinjal', 'Drumstick', 'Bitter Gourd', 'Raw Banana'],
  Fruits: ['Mango', 'Banana', 'Papaya', 'Guava'],
  'Leafy greens': ['Palakura', 'Spinach', 'Methi', 'Coriander'],
}

export default function RegionContent({
  farmers,
  produce,
}: {
  farmers: Record<string, unknown>[]
  produce: Record<string, unknown>[]
}) {
  const { tx } = useLang()
  const [activeFilter, setActiveFilter] = useState('All')
  const [activeTab, setActiveTab] = useState(0)
  const [highlightedFarmerId, setHighlightedFarmerId] = useState<string | null>(null)

  const FILTERS = [tx.all, tx.vegetables, tx.fruits, tx.leafyGreens, tx.naturalOnly]
  const TABS = [tx.farmers, tx.browseProduce, tx.addFarmer]

  // Map filter label back to English key for category lookup
  const filterKeyMap: Record<string, string> = {
    [tx.all]: 'All',
    [tx.vegetables]: 'Vegetables',
    [tx.fruits]: 'Fruits',
    [tx.leafyGreens]: 'Leafy greens',
    [tx.naturalOnly]: 'Natural only',
  }

  const filterKey = filterKeyMap[activeFilter] ?? activeFilter

  const filteredProduce = produce.filter((p) => {
    if (filterKey === 'All') return true
    if (filterKey === 'Natural only') return p.method === 'natural'
    const names = CATEGORY_MAP[filterKey] ?? []
    return names.some((n) => (p.name as string).includes(n))
  })

  const filteredFarmerIds = new Set(filteredProduce.map((p) => p.farmer_id))
  const filteredFarmers = filterKey === 'All'
    ? farmers
    : farmers.filter((f) => filteredFarmerIds.has(f.id))

  return (
    <div>
      {/* Filter chips */}
      <div className="bg-white border-b border-gray-100 px-4 py-3">
        <div className="flex gap-2 overflow-x-auto scrollbar-hide">
          {FILTERS.map((filter) => (
            <button
              key={filter}
              onClick={() => setActiveFilter(filter)}
              className={`flex-shrink-0 px-4 py-1.5 rounded-full text-sm font-semibold border transition-all ${
                activeFilter === filter
                  ? 'bg-green-700 text-white border-green-700'
                  : 'bg-white text-gray-600 border-gray-200'
              }`}
            >
              {filter}
            </button>
          ))}
        </div>
      </div>

      {/* SVG Map */}
      <RegionMap
        farmers={filteredFarmers}
        highlightedFarmerId={highlightedFarmerId}
        onPinClick={setHighlightedFarmerId}
      />

      {/* Tabs */}
      <div className="sticky top-0 z-40 bg-white border-b border-gray-200">
        <div className="flex">
          {TABS.map((tab, i) => (
            <button
              key={tab}
              onClick={() => setActiveTab(i)}
              className={`flex-1 py-3 text-xs font-semibold border-b-2 transition-colors ${
                activeTab === i
                  ? 'border-green-700 text-green-700'
                  : 'border-transparent text-gray-500'
              }`}
            >
              {tab}
            </button>
          ))}
        </div>
      </div>

      <div className="px-4 py-4">
        {activeTab === 0 && (
          <FarmersTab
            farmers={filteredFarmers}
            produce={produce}
            highlightedFarmerId={highlightedFarmerId}
          />
        )}
        {activeTab === 1 && <BrowseProduceTab produce={filteredProduce} farmers={farmers} />}
        {activeTab === 2 && <AddFarmerTab farmerCount={farmers.length} />}
      </div>

      <CartFab />
    </div>
  )
}

'use client'

import { useState } from 'react'
import Link from 'next/link'
import { supabase } from '@/lib/supabase'
import { useLang } from '@/lib/LanguageContext'
import LanguageToggle from '@/components/LanguageToggle'

type Order = {
  id: string
  produce_name: string | null
  quantity: number | null
  unit: string | null
  total_price: number | null
  pickup_location: string | null
  status: 'pending' | 'approved' | 'declined'
  payment_method: string | null
  payment_status: string | null
  created_at: string
  farmer?: {
    name: string
    slug: string
    village: string
    upi_id: string | null
  } | null
}

export default function ConsumerOrdersPage() {
  const { tx } = useLang()
  const [phone, setPhone]     = useState('')
  const [orders, setOrders]   = useState<Order[]>([])
  const [loading, setLoading] = useState(false)
  const [searched, setSearched] = useState(false)
  const [error, setError]     = useState('')

  const digits = phone.replace(/\D/g, '').slice(-10)
  const canSearch = digits.length === 10

  const handleSearch = async () => {
    if (!canSearch) return
    setLoading(true)
    setError('')
    setSearched(false)

    const { data, error: err } = await supabase
      .from('orders')
      .select('id, produce_name, quantity, unit, total_price, pickup_location, status, payment_method, payment_status, created_at, farmer_id')
      .eq('buyer_phone', digits)
      .order('created_at', { ascending: false })
      .limit(50)

    if (err) {
      setError(err.message)
      setLoading(false)
      return
    }

    // Fetch farmer names in one query
    const farmerIds = [...new Set((data ?? []).map((o) => o.farmer_id).filter(Boolean))]
    let farmerMap: Record<string, { name: string; slug: string; village: string; upi_id: string | null }> = {}

    if (farmerIds.length > 0) {
      const { data: farmers } = await supabase
        .from('farmers')
        .select('id, name, slug, village, upi_id')
        .in('id', farmerIds)
      farmerMap = Object.fromEntries(
        (farmers ?? []).map((f) => [f.id, { name: f.name, slug: f.slug, village: f.village, upi_id: (f.upi_id as string | null) ?? null }]),
      )
    }

    const result: Order[] = (data ?? []).map((o) => ({
      ...o,
      farmer: farmerMap[o.farmer_id] ?? null,
    }))

    setOrders(result)
    setSearched(true)
    setLoading(false)
  }

  const statusColor = (s: string) =>
    s === 'approved'
      ? 'bg-green-100 text-green-800'
      : s === 'declined'
      ? 'bg-red-100 text-red-700'
      : 'bg-amber-100 text-amber-800'

  const statusLabel = (s: string) =>
    s === 'approved' ? '✓ Confirmed' : s === 'declined' ? '✕ Declined' : '⏳ Pending'

  const paymentBadge = (order: Order) => {
    if (!order.payment_method || order.payment_method === 'cod') return null
    if (order.payment_method === 'upi') {
      if (order.payment_status === 'completed') return { label: '✓ UPI Paid', cls: 'bg-green-100 text-green-800' }
      if (order.payment_status === 'pending_confirmation' || order.payment_status === 'payment_claimed') return { label: '⏳ Payment sent — awaiting farmer', cls: 'bg-blue-100 text-blue-800' }
      if (order.payment_status === 'failed') return { label: '✕ Payment not received', cls: 'bg-red-100 text-red-800' }
      return { label: '📲 UPI — Pay now', cls: 'bg-orange-100 text-orange-800' }
    }
    return null
  }

  return (
    <main className="min-h-screen bg-gray-50 pb-16">
      {/* Header */}
      <div className="bg-green-900 px-4 pt-6 pb-10">
        <div className="flex items-center justify-between mb-4">
          <Link href="/consumer" className="text-green-300 text-sm flex items-center gap-1">
            ← Back / వెనక్కు
          </Link>
          <LanguageToggle />
        </div>
        <h1 className="text-white text-xl font-extrabold leading-tight">{tx.myOrders}</h1>
        <p className="text-green-400 text-sm mt-1">
          Your complete order history / మీ ఆర్డర్ల చరిత్ర
        </p>
      </div>

      <div className="px-4 -mt-5 space-y-4 max-w-lg mx-auto">
        {/* Phone lookup card */}
        <div className="bg-white rounded-2xl border border-gray-100 p-4 space-y-3">
          <p className="text-sm text-gray-600 leading-snug">
            {tx.enterPhoneForOrders}
          </p>
          <div className="flex gap-2">
            <span className="flex items-center px-3 bg-gray-50 border border-gray-200 rounded-xl text-sm text-gray-600 font-medium whitespace-nowrap">
              +91
            </span>
            <input
              type="tel"
              inputMode="numeric"
              placeholder="9876543210"
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
              className="flex-1 border border-gray-200 rounded-xl px-4 py-3 text-base focus:border-green-500 focus:outline-none"
              maxLength={10}
            />
          </div>
          {error && (
            <p className="text-sm text-red-600 bg-red-50 rounded-xl px-3 py-2">{error}</p>
          )}
          <button
            onClick={handleSearch}
            disabled={loading || !canSearch}
            className="w-full bg-green-700 text-white font-bold py-4 rounded-xl text-base disabled:opacity-50 active:bg-green-800"
          >
            {loading ? 'Searching... / వెతుకుతోంది' : tx.lookupOrders}
          </button>
        </div>

        {/* Results */}
        {searched && orders.length === 0 && (
          <div className="text-center py-14">
            <div className="text-5xl mb-3">📭</div>
            <p className="font-semibold text-gray-500 text-sm">{tx.noOrdersYet}</p>
            <Link href="/consumer" className="mt-4 inline-block text-green-700 text-sm underline font-semibold">
              Browse produce → / పంట చూడండి
            </Link>
          </div>
        )}

        {orders.length > 0 && (
          <div className="space-y-3">
            <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide">
              {orders.length} order{orders.length !== 1 ? 's' : ''} found
            </p>
            {orders.map((order) => {
              const badge = paymentBadge(order)
              const needsPayment = order.payment_method === 'upi'
                && order.payment_status === 'pending'
                && order.farmer?.upi_id
              const upiLink = needsPayment
                ? `upi://pay?pa=${encodeURIComponent(order.farmer!.upi_id!)}&pn=${encodeURIComponent(order.farmer!.name)}&am=${order.total_price ?? 0}&cu=INR&tn=YourFamilyFarmer%20Order`
                : null
              return (
                <div key={order.id} className="bg-white rounded-2xl border border-gray-100 overflow-hidden">
                  <div className="p-4 space-y-2">
                    <div className="flex items-start justify-between gap-2">
                      <div className="min-w-0">
                        <p className="font-extrabold text-gray-900 text-sm leading-tight">
                          {order.produce_name || '—'}
                        </p>
                        <p className="text-xs text-gray-500 mt-0.5">
                          {order.quantity} {order.unit || 'kg'}
                          {order.total_price ? ` · ₹${order.total_price}` : ''}
                        </p>
                      </div>
                      <div className="flex flex-col items-end gap-1 flex-shrink-0">
                        <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full whitespace-nowrap ${statusColor(order.status)}`}>
                          {statusLabel(order.status)}
                        </span>
                        {badge && (
                          <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full whitespace-nowrap ${badge.cls}`}>
                            {badge.label}
                          </span>
                        )}
                      </div>
                    </div>

                    {order.farmer && (
                      <Link
                        href={`/farmer/${order.farmer.slug}`}
                        className="flex items-center gap-1.5 text-xs text-green-700 font-semibold"
                      >
                        🧑‍🌾 {tx.orderedFrom} {order.farmer.name} · {order.farmer.village} ↗
                      </Link>
                    )}

                    {order.pickup_location && (
                      <p className="text-xs text-gray-500">📍 {tx.pickedUpAt}: {order.pickup_location}</p>
                    )}

                    <p className="text-[11px] text-gray-400">
                      {new Date(order.created_at).toLocaleDateString('en-IN', {
                        day: 'numeric',
                        month: 'short',
                        year: 'numeric',
                        hour: '2-digit',
                        minute: '2-digit',
                      })}
                    </p>

                    {/* Pay Now button for pending UPI orders */}
                    {needsPayment && upiLink && (
                      <div className="pt-1 space-y-2">
                        <button
                          onClick={() => { window.location.href = upiLink }}
                          className="w-full bg-green-700 text-white font-bold py-3 rounded-xl text-sm active:bg-green-800"
                        >
                          📲 Pay ₹{order.total_price} via UPI
                        </button>
                        <p className="text-[11px] text-gray-500 text-center">
                          UPI ID: <span className="font-mono font-semibold">{order.farmer?.upi_id}</span>
                        </p>
                      </div>
                    )}
                  </div>
                </div>
              )
            })}
          </div>
        )}
      </div>
    </main>
  )
}

'use client'

import { useState, useEffect, useCallback, useMemo, useRef } from 'react'
import Link from 'next/link'
import GlobalNav from '@/components/consumer/GlobalNav'
import { CartFab, useCart } from '@/components/consumer/Cart'
import { supabase } from '@/lib/supabase'
import { FreshnessBadge } from '@/components/FreshnessBadge'
import { haversineKm, nearestTown, formatDistance } from '@/lib/location'
import LocationSearch from '@/components/LocationSearch'
import { useLang } from '@/lib/LanguageContext'

type PickupSlots = {
  days: string[]
  time_from: string
  time_to: string
}

type Farmer = {
  id: string
  name: string
  village: string
  slug: string
  phone: string
  method: string
  pickup_locations?: string[] | null
  pickup_slots?: PickupSlots | null
  lat?: number | null
  lng?: number | null
}

type ProduceListing = {
  id: string
  name: string
  variety?: string
  emoji?: string
  image_url?: string
  method?: string
  status: string
  price_tier_1_price?: number
  price_tier_1_qty?: number
  price_tier_2_price?: number
  price_tier_2_qty?: number
  price_tier_3_price?: number
  price_tier_3_qty?: number
  stock_qty?: number
  unit?: string
  available_to?: string
  harvest_date?: string | null
  farmer_id: string
  farmer?: Farmer
}

const CATEGORIES = [
  { key: 'all',        en: 'All',             te: 'అన్నీ' },
  { key: 'vegetables', en: 'Vegetables',      te: 'కూరగాయలు' },
  { key: 'fruits',     en: 'Fruits',          te: 'పళ్ళు' },
  { key: 'grains',     en: 'Grains & Pulses', te: 'ధాన్యాలు' },
  { key: 'leafy',      en: 'Leafy Greens',    te: 'ఆకు కూరలు' },
]

const EMOJI_BG: Record<string, string> = {
  '🍅': 'bg-red-100',    '🥬': 'bg-green-100',  '🥭': 'bg-orange-100',
  '🍆': 'bg-purple-100', '🥕': 'bg-orange-100', '🌽': 'bg-yellow-100',
  '🍌': 'bg-yellow-100', '🫑': 'bg-green-100',  '🧅': 'bg-orange-50',
  '🧄': 'bg-amber-50',   '🍓': 'bg-red-50',     '🥦': 'bg-green-100',
  '🌾': 'bg-amber-100',  '🫒': 'bg-green-100',  '🌿': 'bg-green-50',
  '🥥': 'bg-orange-50',  '🍇': 'bg-purple-50',  '🍋': 'bg-yellow-50',
}

const METHOD_STYLE: Record<string, string> = {
  natural:      'bg-green-100 text-green-800',
  organic:      'bg-teal-100  text-teal-800',
  low_chemical: 'bg-amber-100 text-amber-800',
  chemical:     'bg-red-100   text-red-700',
}

const METHOD_LABEL: Record<string, string> = {
  natural:      'Natural / సహజం',
  organic:      'Organic / సేంద్రీయ',
  low_chemical: 'Low chemical',
  chemical:     'Chemical',
}

export default function ConsumerPage() {
  const [available, setAvailable]     = useState<ProduceListing[]>([])
  const [comingSoon, setComingSoon]   = useState<ProduceListing[]>([])
  const [filtered, setFiltered]       = useState<ProduceListing[]>([])
  const [search, setSearch]           = useState('')
  const [method, setMethod]           = useState('all')
  const [category, setCategory]       = useState('all')
  const [loading, setLoading]         = useState(true)
  const [farmerCount, setFarmerCount] = useState(0)
  const searchAbortRef = useRef<AbortController | null>(null)

  // Consumer location
  const [consumerLat, setConsumerLat]           = useState<number | null>(null)
  const [consumerLng, setConsumerLng]           = useState<number | null>(null)
  const [consumerLocationName, setConsumerLocationName] = useState('')
  const [showLocationSheet, setShowLocationSheet]       = useState(false)
  const [distanceFilter, setDistanceFilter]             = useState<number | null>(null)

  const fetchData = useCallback(async (silent = false) => {
    if (!silent) setLoading(true)
    try {
      const [avRes, csRes] = await Promise.all([
        fetch('/api/produce', { cache: 'no-store' }),
        fetch('/api/produce?status=coming_soon', { cache: 'no-store' }),
      ])
      const av: ProduceListing[] = await avRes.json().catch(() => [])
      const cs: ProduceListing[] = await csRes.json().catch(() => [])
      const avArr = Array.isArray(av) ? av : []
      const csArr = Array.isArray(cs) ? cs : []
      setAvailable(avArr)
      setFiltered(avArr)
      setComingSoon(csArr)
      setFarmerCount(new Set(avArr.map((p) => p.farmer_id)).size)
    } catch { /* silent */ }
    if (!silent) setLoading(false)
  }, [])

  useEffect(() => {
    fetchData()
    // Background refreshes — no skeleton flash
    const onVisible = () => { if (document.visibilityState === 'visible') fetchData(true) }
    document.addEventListener('visibilitychange', onVisible)
    const channel = supabase
      .channel('produce_listings_consumer')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'produce_listings' }, () => fetchData(true))
      .subscribe()
    return () => {
      document.removeEventListener('visibilitychange', onVisible)
      supabase.removeChannel(channel)
    }
  }, [fetchData])

  const doSearch = useCallback(async () => {
    if (!search && method === 'all' && category === 'all') {
      setFiltered(available)
      return
    }
    searchAbortRef.current?.abort()
    searchAbortRef.current = new AbortController()
    try {
      const p = new URLSearchParams()
      if (search)              p.set('q', search)
      if (method !== 'all')    p.set('method', method)
      if (category !== 'all')  p.set('category', category)
      const res = await fetch(`/api/produce/search?${p}`, { cache: 'no-store', signal: searchAbortRef.current.signal })
      const data = await res.json().catch(() => [])
      setFiltered(Array.isArray(data) ? data : [])
    } catch (e) {
      if ((e as Error).name !== 'AbortError') { /* silent */ }
    }
  }, [search, method, category, available])

  useEffect(() => {
    const t = setTimeout(doSearch, 300)
    return () => clearTimeout(t)
  }, [doSearch])

  // Load consumer location from localStorage
  useEffect(() => {
    const lat  = localStorage.getItem('yff_consumer_lat')
    const lng  = localStorage.getItem('yff_consumer_lng')
    const name = localStorage.getItem('yff_consumer_location_name')
    if (lat && lng) {
      setConsumerLat(Number(lat))
      setConsumerLng(Number(lng))
      setConsumerLocationName(name ?? '')
    } else if (!localStorage.getItem('yff_location_prompted')) {
      setShowLocationSheet(true)
    }
  }, [])

  const saveConsumerLocation = useCallback((lat: number, lng: number, name: string) => {
    setConsumerLat(lat)
    setConsumerLng(lng)
    setConsumerLocationName(name)
    localStorage.setItem('yff_consumer_lat', String(lat))
    localStorage.setItem('yff_consumer_lng', String(lng))
    localStorage.setItem('yff_consumer_location_name', name)
    localStorage.setItem('yff_location_prompted', '1')
    setShowLocationSheet(false)
  }, [])

  // Sort + distance-filter produce
  const displayItems = useMemo(() => {
    type WithDist = ProduceListing & { distKm: number | null }
    const withDist: WithDist[] = filtered.map((item) => ({
      ...item,
      distKm: (consumerLat && consumerLng && item.farmer?.lat && item.farmer?.lng)
        ? haversineKm(consumerLat, consumerLng, item.farmer.lat, item.farmer.lng)
        : null,
    }))
    if (!consumerLat || !consumerLng) return withDist
    let result = withDist
    if (distanceFilter) {
      result = result.filter((i) => i.distKm !== null && i.distKm <= distanceFilter)
    }
    return result.sort((a, b) => {
      if (a.distKm === null && b.distKm === null) return 0
      if (a.distKm === null) return 1
      if (b.distKm === null) return -1
      return a.distKm - b.distKm
    })
  }, [filtered, consumerLat, consumerLng, distanceFilter])

  return (
    <main className="min-h-screen bg-gray-50 pb-12">
      <GlobalNav activeTab="consumer" />

      {/* ── Hero ─────────────────────────────── */}
      <div className="bg-green-900">
        <div className="max-w-3xl mx-auto px-4 pt-8 pb-14">
          <h1 className="text-2xl sm:text-4xl font-extrabold text-white leading-snug">
            Fresh from your<br />local farmer
          </h1>
          <p className="text-green-300 text-base sm:text-lg mt-1 font-medium">
            మీ స్థానిక రైతు నుండి తాజా ఆహారం
          </p>
          <p className="text-green-400 text-sm mt-1">
            Straight from farm · No middlemen / నేరుగా పొలం నుండి · మధ్యవర్తులు లేరు
          </p>

          {/* Stats */}
          <div className="flex gap-8 mt-6">
            {[
              { val: farmerCount,       en: 'Farmers',    te: 'రైతులు' },
              { val: available.length,  en: 'Products',   te: 'పంటలు' },
              { val: 0,                 en: 'Middlemen',  te: 'మధ్యవర్తులు' },
            ].map((s) => (
              <div key={s.en}>
                <div className="text-4xl font-black text-white">{s.val}</div>
                <div className="text-xs text-green-300 mt-0.5 leading-snug">
                  {s.en}<br />{s.te}
                </div>
              </div>
            ))}
          </div>

          {/* Location pill */}
          <div className="flex flex-wrap items-center gap-2 mt-5">
            <button
              onClick={() => setShowLocationSheet(true)}
              className="inline-flex items-center gap-1.5 bg-green-800 border border-green-700 text-green-200 text-sm font-semibold px-4 py-2.5 rounded-full active:bg-green-700"
            >
              📍 {consumerLocationName || 'Set location / లొకేషన్ పెట్టండి'}
              <span className="text-green-400 text-xs ml-0.5">✎</span>
            </button>
            <Link
              href="/consumer/orders"
              className="inline-flex items-center gap-2 bg-green-800 border border-green-700 text-green-200 text-xs font-semibold px-4 py-2.5 rounded-full"
            >
              📦 My Orders / నా ఆర్డర్లు →
            </Link>
          </div>
        </div>
      </div>

      {/* ── Search card (floats over hero) ────── */}
      <div className="max-w-3xl mx-auto px-4 -mt-7">
        <div className="bg-white rounded-2xl shadow-xl p-4 space-y-3">
          <div className="relative">
            <svg className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
              <circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35" strokeLinecap="round"/>
            </svg>
            <input
              type="search"
              placeholder="Search produce... / పంట వెతకండి..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full pl-10 pr-4 py-3 border-2 border-gray-200 rounded-xl text-base focus:border-green-500 focus:outline-none"
            />
          </div>
          <select
            value={method}
            onChange={(e) => setMethod(e.target.value)}
            className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl text-base bg-white focus:border-green-500 focus:outline-none"
          >
            <option value="all">🌿 All methods / అన్ని పద్ధతులు</option>
            <option value="natural">🌱 Natural / సహజం</option>
            <option value="organic">🍃 Organic / సేంద్రీయ</option>
            <option value="low_chemical">⚡ Low chemical / తక్కువ రసాయన</option>
          </select>
        </div>
      </div>

      {/* ── Category chips ───────────────────── */}
      <div className="max-w-3xl mx-auto mt-4 px-4">
        <div className="flex gap-2 overflow-x-auto scrollbar-hide pb-1">
          {CATEGORIES.map((chip) => (
            <button
              key={chip.key}
              onClick={() => setCategory(chip.key)}
              className={`flex-shrink-0 px-4 py-2.5 rounded-full text-sm font-semibold border transition-all ${
                category === chip.key
                  ? 'bg-green-700 text-white border-green-700'
                  : 'bg-white text-gray-700 border-gray-200'
              }`}
            >
              {chip.en} / {chip.te}
            </button>
          ))}
        </div>
      </div>

      {/* ── Distance filter chips (only when location set) ── */}
      {consumerLat && consumerLng && (
        <div className="max-w-3xl mx-auto mt-3 px-4">
          <div className="flex gap-2 overflow-x-auto scrollbar-hide pb-1">
            {([null, 5, 10, 25] as const).map((d) => (
              <button
                key={d ?? 'all'}
                onClick={() => setDistanceFilter(d)}
                className={`flex-shrink-0 px-4 py-2 rounded-full text-sm font-semibold border transition-all ${
                  distanceFilter === d
                    ? 'bg-green-700 text-white border-green-700'
                    : 'bg-white text-gray-700 border-gray-200'
                }`}
              >
                {d === null ? 'All / అన్నీ' : `< ${d} km`}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* ── Available now ────────────────────── */}
      <div className="max-w-3xl mx-auto px-4 mt-6">
        <div className="flex items-end justify-between mb-4">
          <div>
            <h2 className="text-xl font-extrabold text-gray-900">Available now / ఇప్పుడు అందుబాటులో</h2>
            <p className="text-green-700 font-semibold text-sm leading-tight">
              Fresh produce from farms nearby / తాజా పంట
            </p>
          </div>
          {!loading && (
            <span className="text-sm font-bold text-gray-400">
              {displayItems.length} items / వస్తువులు
            </span>
          )}
        </div>

        {loading ? (
          <LoadingSkeleton />
        ) : displayItems.length === 0 ? (
          distanceFilter ? (
            <DistanceEmptyState km={distanceFilter} onClear={() => setDistanceFilter(null)} />
          ) : (
            <EmptyState />
          )
        ) : (
          <div className="grid grid-cols-2 gap-3">
            {displayItems.map((item) => (
              <ProduceCard key={item.id} item={item} distanceKm={'distKm' in item ? (item as ProduceListing & { distKm: number | null }).distKm : null} />
            ))}
          </div>
        )}
      </div>

      {/* ── Coming soon ──────────────────────── */}
      {!loading && comingSoon.length > 0 && (
        <div className="max-w-3xl mx-auto px-4 mt-10">
          <div className="mb-4">
            <h2 className="text-xl font-extrabold text-gray-900">Coming soon / త్వరలో వస్తుంది</h2>
            <p className="text-amber-600 font-semibold text-sm">
              Reserve early / ముందుగానే రిజర్వ్
            </p>
          </div>
          <div className="grid grid-cols-2 gap-3">
            {comingSoon.map((item) => (
              <ComingSoonCard key={item.id} item={item} />
            ))}
          </div>
        </div>
      )}

      {/* ── Demand intent banner ─────────────── */}
      <DemandIntentBanner />

      {/* ── Floating cart button ─────────────── */}
      <CartFab />

      {/* ── Location bottom sheet ─────────────── */}
      {showLocationSheet && (
        <LocationBottomSheet
          onSet={saveConsumerLocation}
          onClose={() => {
            localStorage.setItem('yff_location_prompted', '1')
            setShowLocationSheet(false)
          }}
        />
      )}
    </main>
  )
}

/* ─── Produce card ──────────────────────────────────────── */
function ProduceCard({ item, distanceKm }: { item: ProduceListing; distanceKm?: number | null }) {
  const emoji      = item.emoji ?? '🌿'
  const emojiBg    = EMOJI_BG[emoji] ?? 'bg-green-50'
  const method     = item.method?.toLowerCase() ?? 'natural'
  const badge      = METHOD_STYLE[method]  ?? 'bg-green-100 text-green-800'
  const badgeLabel = METHOD_LABEL[method] ?? 'Natural'
  const farmer     = item.farmer
  const farmerHref = farmer ? `/farmer/${farmer.slug}` : '#'
  const unit       = item.unit || 'kg'

  const { tx } = useLang()
  const { cart, addItem, setQty } = useCart()
  const inCart = cart[item.id]

  const canAdd = !!farmer && !!farmer.phone

  const [liveStock, setLiveStock] = useState<number | null>(item.stock_qty ?? null)
  const [stockMsg, setStockMsg]   = useState('')
  const [adding, setAdding]       = useState(false)

  useEffect(() => { setLiveStock(item.stock_qty ?? null) }, [item.stock_qty])

  const isOutOfStock = liveStock !== null && liveStock <= 0
  const atMax        = liveStock !== null && inCart != null && inCart.qty >= liveStock

  const handleAdd = async () => {
    if (!farmer) return
    setAdding(true)
    setStockMsg('')

    const { data } = await supabase
      .from('produce_listings')
      .select('stock_qty')
      .eq('id', item.id)
      .single()

    const fresh = data?.stock_qty ?? null
    if (fresh !== null) setLiveStock(fresh)
    setAdding(false)

    if (fresh !== null) {
      if (fresh <= 0) {
        setStockMsg('Out of stock / అయిపోయింది')
        return
      }
      const curQty = inCart?.qty ?? 0
      if (curQty >= fresh) {
        setStockMsg(`Maximum available / గరిష్ట పరిమాణం: ${fresh} ${unit}`)
        return
      }
      if (curQty + 1 > fresh) {
        setStockMsg(`Stock updated / స్టాక్ మారింది, only ${fresh} ${unit} available`)
        return
      }
    }

    addItem({
      listingId: item.id,
      name: item.name,
      variety: item.variety,
      emoji: item.emoji,
      unit,
      stockQty: fresh != null ? fresh : (item.stock_qty ?? undefined),
      pricePerKg: item.price_tier_1_price,
      priceTier1Qty: item.price_tier_1_qty,
      priceTier1Price: item.price_tier_1_price,
      priceTier2Qty: item.price_tier_2_qty,
      priceTier2Price: item.price_tier_2_price,
      priceTier3Price: item.price_tier_3_price,
      farmerId: farmer.id,
      farmerName: farmer.name,
      farmerPhone: farmer.phone,
      farmerVillage: farmer.village,
      farmerSlug: farmer.slug,
      farmerPickupLocations: farmer.pickup_locations ?? [],
      farmerPickupSlots: farmer.pickup_slots ?? null,
    }, 1)
  }

  const handleInc = () => {
    if (liveStock !== null && inCart.qty >= liveStock) {
      setStockMsg(`Maximum available / గరిష్ట పరిమాణం: ${liveStock} ${unit}`)
      return
    }
    setStockMsg('')
    setQty(item.id, inCart.qty + 1)
  }

  return (
    <div className="bg-white rounded-2xl overflow-hidden shadow-sm border border-gray-100 flex flex-col">
      {/* Image (or emoji fallback) */}
      <Link href={farmerHref}>
        {item.image_url ? (
          <div className="bg-gray-100 aspect-[4/3] overflow-hidden">
            <img
              src={item.image_url}
              alt={item.name}
              loading="lazy"
              className="w-full h-full object-cover"
            />
          </div>
        ) : (
          <div className={`${emojiBg} flex items-center justify-center py-7`}>
            <span className="text-5xl">{emoji}</span>
          </div>
        )}
      </Link>

      <div className="p-3 flex flex-col flex-1 gap-1">
        {/* Name + variety */}
        <Link href={farmerHref}>
          <h3 className="font-extrabold text-gray-900 text-base leading-tight">{item.name}</h3>
          {item.variety && (
            <p className="text-xs text-gray-400 mt-0.5">{item.variety}</p>
          )}
        </Link>

        {/* Farmer info */}
        {farmer && (
          <div className="flex items-center justify-between gap-2">
            <span className="text-xs text-gray-500 leading-snug">
              🧑‍🌾 {farmer.name}<br />
              📍 {farmer.village}
            </span>
            <Link
              href={farmerHref}
              className="flex-shrink-0 text-[11px] font-semibold text-green-700 border border-green-300 rounded-full px-2.5 py-1 bg-green-50 active:bg-green-100 whitespace-nowrap"
            >
              {tx.viewFarmerProfile}
            </Link>
          </div>
        )}

        {/* Distance badge */}
        {distanceKm != null && (
          <span className="inline-flex items-center gap-0.5 text-[11px] font-semibold text-blue-700 bg-blue-50 px-2 py-0.5 rounded-full self-start">
            📍 {formatDistance(distanceKm)} away
          </span>
        )}

        {/* Price + method badge */}
        <div className="flex items-center justify-between mt-1">
          <span className="text-green-700 font-black text-lg">
            {item.price_tier_1_price ? `₹${item.price_tier_1_price}` : '—'}
            <span className="text-xs font-normal text-gray-400">/{unit}</span>
          </span>
          <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${badge}`}>
            {badgeLabel}
          </span>
        </div>

        {/* Freshness badge */}
        {item.harvest_date && <FreshnessBadge harvestDate={item.harvest_date} />}

        {/* Stock display */}
        {liveStock != null && (
          <p className={`text-xs font-medium ${liveStock === 0 ? 'text-red-500' : 'text-gray-400'}`}>
            {liveStock === 0
              ? 'Out of stock / అయిపోయింది'
              : `${liveStock} ${unit} left / మిగిలాయి`}
          </p>
        )}

        {/* Stock warning */}
        {stockMsg && (
          <p className="text-xs text-amber-700 bg-amber-50 border border-amber-200 rounded-lg px-2 py-1 leading-snug text-center">
            {stockMsg}
          </p>
        )}

        {/* CTA */}
        {!canAdd ? (
          <Link
            href={farmerHref}
            className="mt-2 block text-center w-full bg-green-700 text-white font-bold py-3 rounded-xl text-sm"
          >
            View / చూడండి
          </Link>
        ) : isOutOfStock ? (
          <button
            disabled
            className="mt-2 w-full bg-gray-200 text-gray-500 font-bold py-3 rounded-xl text-sm cursor-not-allowed"
          >
            Out of stock / అయిపోయింది
          </button>
        ) : !inCart ? (
          <button
            onClick={handleAdd}
            disabled={adding}
            className="mt-2 w-full bg-green-700 active:bg-green-800 text-white font-bold py-3 rounded-xl text-sm disabled:opacity-60"
          >
            {adding ? 'Checking... / తనిఖీ' : '+ Add to cart / చేర్చు'}
          </button>
        ) : (
          <div className="mt-2 flex items-center justify-between bg-green-50 border border-green-200 rounded-xl px-2 py-1.5">
            <button
              onClick={() => { setQty(item.id, inCart.qty - 1); setStockMsg('') }}
              className="w-8 h-8 rounded-lg bg-white border border-green-300 text-green-800 text-lg font-bold"
              aria-label="Decrease"
            >
              −
            </button>
            <span className="font-extrabold text-green-900 text-sm">
              {inCart.qty} {unit}
            </span>
            <button
              onClick={handleInc}
              disabled={atMax}
              className={`w-8 h-8 rounded-lg text-lg font-bold transition-colors ${
                atMax
                  ? 'bg-gray-200 text-gray-400 cursor-not-allowed'
                  : 'bg-green-700 text-white'
              }`}
              aria-label="Increase"
            >
              +
            </button>
          </div>
        )}
      </div>
    </div>
  )
}

